 1→package jlsm.table;
 2→
 3→import java.lang.foreign.MemorySegment;
 4→import java.util.Objects;
 5→
 6→/**
 7→ * Describes a single partition in a {@link PartitionedTable}.
 8→ *
 9→ * <p>
10→ * Contract: Immutable descriptor holding the key range boundaries, partition identity, and location
11→ * metadata. The key range is half-open: [{@code lowKey} inclusive, {@code highKey} exclusive).
12→ *
13→ * <p>
14→ * Governed by: .decisions/table-partitioning/adr.md — range partitioning with co-located indices.
15→ *
16→ * @param id unique partition identifier
17→ * @param lowKey inclusive lower bound of the key range (lexicographic byte order)
18→ * @param highKey exclusive upper bound of the key range (lexicographic byte order)
19→ * @param nodeId location identifier — local ID for in-process, URI for remote (future)
20→ * @param epoch logical clock incremented on partition config changes (split, merge, reassign)
21→ */
22→public record PartitionDescriptor(long id, MemorySegment lowKey, MemorySegment highKey,
23→        String nodeId, long epoch) {
24→
25→    public PartitionDescriptor {
26→        Objects.requireNonNull(lowKey, "lowKey must not be null");
27→        Objects.requireNonNull(highKey, "highKey must not be null");
28→        Objects.requireNonNull(nodeId, "nodeId must not be null");
29→        if (epoch < 0) {
30→            throw new IllegalArgumentException("epoch must be non-negative, got: " + epoch);
31→        }
32→    }
33→}
