 33→    private final AtomicLong idCounter = new AtomicLong(0);
 34→
 35→    private JlsmSchema testSchema() {
 36→        return JlsmSchema.builder("test", 1).field("name", FieldType.Primitive.STRING)
 37→                .field("age", FieldType.Primitive.INT32).field("email", FieldType.Primitive.STRING)
 38→                .build();
 39→    }
