 41→    private TypedLsmTree.StringKeyed<JlsmDocument> buildStringTree(Path dir, JlsmSchema schema)
 42→            throws IOException {
 43→        final MemorySerializer<JlsmDocument> codec = DocumentSerializer.forSchema(schema);
 44→        return TypedStandardLsmTree.<JlsmDocument>stringKeyedBuilder()
 45→                .wal(LocalWriteAheadLog.builder().directory(dir).build())
 46→                .memTableFactory(ConcurrentSkipListMemTable::new)
 47→                .sstableWriterFactory((SSTableWriterFactory) (id, level,
 48→                        path) -> new TrieSSTableWriter(id, level, path))
 49→                .sstableReaderFactory((SSTableReaderFactory) path -> TrieSSTableReader.open(path,
 50→                        BlockedBloomFilter.deserializer()))
 51→                .idSupplier(idCounter::getAndIncrement)
 52→                .pathFn((id, level) -> dir.resolve("sst-" + id + "-L" + level.index() + ".sst"))
 53→                .memTableFlushThresholdBytes(1024 * 1024).valueSerializer(codec).build();
 54→    }
 55→
 56→    private TypedLsmTree.LongKeyed<JlsmDocument> buildLongTree(Path dir, JlsmSchema schema)
 57→            throws IOException {
 58→        final MemorySerializer<JlsmDocument> codec = DocumentSerializer.forSchema(schema);
 59→        return TypedStandardLsmTree.<JlsmDocument>longKeyedBuilder()
 60→                .wal(LocalWriteAheadLog.builder().directory(dir).build())
 61→                .memTableFactory(ConcurrentSkipListMemTable::new)
 62→                .sstableWriterFactory((SSTableWriterFactory) (id, level,
 63→                        path) -> new TrieSSTableWriter(id, level, path))
 64→                .sstableReaderFactory((SSTableReaderFactory) path -> TrieSSTableReader.open(path,
 65→                        BlockedBloomFilter.deserializer()))
 66→                .idSupplier(idCounter::getAndIncrement)
 67→                .pathFn((id, level) -> dir.resolve("sst-" + id + "-L" + level.index() + ".sst"))
 68→                .memTableFlushThresholdBytes(1024 * 1024).valueSerializer(codec).build();
 69→    }
