276→                        .build()) {
277→            table.create(1L, JlsmDocument.of(schema, "name", "One", "age", 1));
278→            table.create(2L, JlsmDocument.of(schema, "name", "Two", "age", 2));
279→            table.create(3L, JlsmDocument.of(schema, "name", "Three", "age", 3));
280→            table.create(4L, JlsmDocument.of(schema, "name", "Four", "age", 4));
281→            table.create(5L, JlsmDocument.of(schema, "name", "Five", "age", 5));
282→
283→            final Iterator<TableEntry<Long>> it = table.getAllInRange(2L, 5L);
284→            final List<TableEntry<Long>> entries = new ArrayList<>();
285→            while (it.hasNext()) {
286→                entries.add(it.next());
287→            }
288→
289→            assertEquals(3, entries.size(), "half-open range [2, 5) should return 2, 3, 4");
290→            assertEquals(2L, entries.get(0).key());
291→            assertEquals("Two", entries.get(0).document().getString("name"));
292→            assertEquals(3L, entries.get(1).key());
293→            assertEquals("Three", entries.get(1).document().getString("name"));
294→            assertEquals(4L, entries.get(2).key());
295→            assertEquals("Four", entries.get(2).document().getString("name"));
296→        }
297→    }
298→}
