package jlsm.table.internal;

import jlsm.table.JlsmDocument;
import jlsm.table.JlsmSchema;
import jlsm.table.FieldType;
import jlsm.table.ScoredEntry;
import jlsm.table.TableEntry;

import org.junit.jupiter.api.Test;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.Iterator;
import java.util.List;

import static org.junit.jupiter.api.Assertions.*;

class ResultMergerTest {

    private static JlsmSchema testSchema() {
        return JlsmSchema.builder("test", 1).field("name", FieldType.Primitive.STRING).build();
    }

    private static JlsmDocument doc(JlsmSchema schema, String name) {
        return JlsmDocument.of(schema, "name", name);
    }

    // -------------------------------------------------------------------------
    // mergeTopK — null / bad input
    // -------------------------------------------------------------------------

    @Test
    void mergeTopK_nullPartitionResults_throwsNullPointerException() {
        assertThrows(NullPointerException.class, () -> ResultMerger.mergeTopK(null, 5));
    }

    @Test
    void mergeTopK_negativeK_throwsIllegalArgumentException() {
        assertThrows(IllegalArgumentException.class,
                () -> ResultMerger.mergeTopK(List.of(), -1));
    }

    @Test
    void mergeTopK_zeroK_throwsIllegalArgumentException() {
        assertThrows(IllegalArgumentException.class,
                () -> ResultMerger.mergeTopK(List.of(), 0));
    }

    // -------------------------------------------------------------------------
    // mergeTopK — correctness
    // -------------------------------------------------------------------------

    @Test
    void mergeTopK_emptyPartitions_returnsEmptyList() {
        final List<ScoredEntry<String>> result = ResultMerger.mergeTopK(List.of(), 5);
        assertTrue(result.isEmpty(), "empty partitions should produce empty result");
    }

    @Test
    void mergeTopK_singlePartition_returnsTopK() {
        final JlsmSchema schema = testSchema();
        final List<ScoredEntry<String>> partition = List.of(
                new ScoredEntry<>("a", doc(schema, "A"), 0.9),
                new ScoredEntry<>("b", doc(schema, "B"), 0.7),
                new ScoredEntry<>("c", doc(schema, "C"), 0.5));

        final List<ScoredEntry<String>> result = ResultMerger.mergeTopK(List.of(partition), 2);

        assertEquals(2, result.size(), "should return exactly k results");
        assertEquals("a", result.get(0).key(), "highest score should be first");
        assertEquals("b", result.get(1).key(), "second highest should be next");
    }

    @Test
    void mergeTopK_multiplePartitions_mergesAndSortsByScoreDescending() {
        final JlsmSchema schema = testSchema();
        final List<ScoredEntry<String>> p1 = List.of(
                new ScoredEntry<>("a", doc(schema, "A"), 0.95),
                new ScoredEntry<>("c", doc(schema, "C"), 0.60));
        final List<ScoredEntry<String>> p2 = List.of(
                new ScoredEntry<>("b", doc(schema, "B"), 0.85),
                new ScoredEntry<>("d", doc(schema, "D"), 0.40));

        final List<ScoredEntry<String>> result = ResultMerger.mergeTopK(List.of(p1, p2), 3);

        assertEquals(3, result.size());
        assertEquals("a", result.get(0).key(), "score 0.95 is highest");
        assertEquals("b", result.get(1).key(), "score 0.85 is second");
        assertEquals("c", result.get(2).key(), "score 0.60 is third");
    }

    @Test
    void mergeTopK_kExceedsTotalEntries_returnsAll() {
        final JlsmSchema schema = testSchema();
        final List<ScoredEntry<String>> partition = List.of(
                new ScoredEntry<>("x", doc(schema, "X"), 0.5));

        final List<ScoredEntry<String>> result = ResultMerger.mergeTopK(List.of(partition), 100);

        assertEquals(1, result.size(), "should return all available entries when k > total");
    }

    @Test
    void mergeTopK_emptyAndNonEmptyPartitions_mergesCorrectly() {
        final JlsmSchema schema = testSchema();
        final List<ScoredEntry<String>> p1 = List.of();
        final List<ScoredEntry<String>> p2 = List.of(
                new ScoredEntry<>("x", doc(schema, "X"), 0.8));

        final List<ScoredEntry<String>> result = ResultMerger.mergeTopK(List.of(p1, p2), 5);

        assertEquals(1, result.size());
        assertEquals("x", result.get(0).key());
    }

    @Test
    void mergeTopK_resultIsSortedByScoreDescending() {
        final JlsmSchema schema = testSchema();
        final List<ScoredEntry<String>> p1 = List.of(
                new ScoredEntry<>("low", doc(schema, "Low"), 0.1),
                new ScoredEntry<>("high", doc(schema, "High"), 0.9));
        final List<ScoredEntry<String>> p2 = List.of(
                new ScoredEntry<>("mid", doc(schema, "Mid"), 0.5));

        final List<ScoredEntry<String>> result = ResultMerger.mergeTopK(List.of(p1, p2), 3);

        assertEquals(3, result.size());
        assertTrue(result.get(0).score() >= result.get(1).score(),
                "results must be ordered by score descending");
        assertTrue(result.get(1).score() >= result.get(2).score(),
                "results must be ordered by score descending");
    }

    // -------------------------------------------------------------------------
    // mergeOrdered — null / bad input
    // -------------------------------------------------------------------------

    @Test
    void mergeOrdered_nullList_throwsNullPointerException() {
        assertThrows(NullPointerException.class, () -> ResultMerger.mergeOrdered(null));
    }

    // -------------------------------------------------------------------------
    // mergeOrdered — correctness
    // -------------------------------------------------------------------------

    @Test
    void mergeOrdered_emptyIteratorList_returnsEmptyIterator() {
        final Iterator<TableEntry<String>> it = ResultMerger.mergeOrdered(List.of());
        assertFalse(it.hasNext(), "empty iterator list should produce empty iterator");
    }

    @Test
    void mergeOrdered_singleIterator_returnsAllEntriesInOrder() {
        final JlsmSchema schema = testSchema();
        final List<TableEntry<String>> entries = List.of(
                new TableEntry<>("a", doc(schema, "A")),
                new TableEntry<>("b", doc(schema, "B")),
                new TableEntry<>("c", doc(schema, "C")));

        final Iterator<TableEntry<String>> it =
                ResultMerger.mergeOrdered(List.of(entries.iterator()));
        final List<TableEntry<String>> result = drainIterator(it);

        assertEquals(3, result.size());
        assertEquals("a", result.get(0).key());
        assertEquals("b", result.get(1).key());
        assertEquals("c", result.get(2).key());
    }

    @Test
    void mergeOrdered_twoDisjointPartitions_mergesInKeyOrder() {
        final JlsmSchema schema = testSchema();
        final List<TableEntry<String>> p1 = List.of(
                new TableEntry<>("b", doc(schema, "B")),
                new TableEntry<>("d", doc(schema, "D")));
        final List<TableEntry<String>> p2 = List.of(
                new TableEntry<>("a", doc(schema, "A")),
                new TableEntry<>("c", doc(schema, "C")));

        final Iterator<TableEntry<String>> it =
                ResultMerger.mergeOrdered(List.of(p1.iterator(), p2.iterator()));
        final List<TableEntry<String>> result = drainIterator(it);

        assertEquals(4, result.size());
        assertEquals("a", result.get(0).key());
        assertEquals("b", result.get(1).key());
        assertEquals("c", result.get(2).key());
        assertEquals("d", result.get(3).key());
    }

    @Test
    void mergeOrdered_oneEmptyPartition_returnsNonEmptyPartitionEntries() {
        final JlsmSchema schema = testSchema();
        final List<TableEntry<String>> p1 = List.of();
        final List<TableEntry<String>> p2 = List.of(
                new TableEntry<>("x", doc(schema, "X")),
                new TableEntry<>("y", doc(schema, "Y")));

        final Iterator<TableEntry<String>> it =
                ResultMerger.mergeOrdered(List.of(p1.iterator(), p2.iterator()));
        final List<TableEntry<String>> result = drainIterator(it);

        assertEquals(2, result.size());
        assertEquals("x", result.get(0).key());
        assertEquals("y", result.get(1).key());
    }

    @Test
    void mergeOrdered_multiplePartitions_globalKeyOrder() {
        final JlsmSchema schema = testSchema();
        final List<TableEntry<String>> p1 = List.of(
                new TableEntry<>("apple", doc(schema, "Apple")),
                new TableEntry<>("cherry", doc(schema, "Cherry")));
        final List<TableEntry<String>> p2 = List.of(
                new TableEntry<>("banana", doc(schema, "Banana")),
                new TableEntry<>("date", doc(schema, "Date")));
        final List<TableEntry<String>> p3 = List.of(
                new TableEntry<>("avocado", doc(schema, "Avocado")));

        final Iterator<TableEntry<String>> it =
                ResultMerger.mergeOrdered(List.of(p1.iterator(), p2.iterator(), p3.iterator()));
        final List<TableEntry<String>> result = drainIterator(it);

        assertEquals(5, result.size());
        // Lexicographic order: apple, avocado, banana, cherry, date
        assertEquals("apple", result.get(0).key());
        assertEquals("avocado", result.get(1).key());
        assertEquals("banana", result.get(2).key());
        assertEquals("cherry", result.get(3).key());
        assertEquals("date", result.get(4).key());
    }

    @Test
    void mergeOrdered_isLazy_doesNotEagerlyDrain() {
        final JlsmSchema schema = testSchema();
        // Verify iterator is lazy by checking hasNext/next behave correctly on demand
        final List<TableEntry<String>> entries = List.of(
                new TableEntry<>("a", doc(schema, "A")),
                new TableEntry<>("b", doc(schema, "B")));

        final Iterator<TableEntry<String>> it =
                ResultMerger.mergeOrdered(List.of(entries.iterator()));

        assertTrue(it.hasNext());
        assertEquals("a", it.next().key());
        assertTrue(it.hasNext());
        assertEquals("b", it.next().key());
        assertFalse(it.hasNext());
    }

    // -------------------------------------------------------------------------
    // Helper
    // -------------------------------------------------------------------------

    private static <T> List<T> drainIterator(Iterator<T> it) {
        final List<T> result = new ArrayList<>();
        while (it.hasNext()) {
            result.add(it.next());
        }
        return result;
    }
}

package jlsm.table.internal;

import jlsm.table.JlsmDocument;
import jlsm.table.JlsmTable;
import jlsm.table.PartitionClient;
import jlsm.table.PartitionDescriptor;
import jlsm.table.Predicate;
import jlsm.table.ScoredEntry;
import jlsm.table.TableEntry;
import jlsm.table.UpdateMode;

import java.io.IOException;
import java.util.Iterator;
import java.util.List;
import java.util.Objects;
import java.util.Optional;

/**
 * In-process implementation of {@link PartitionClient} that wraps a {@link JlsmTable.StringKeyed}.
 *
 * <p>
 * Contract: Delegates all operations directly to the wrapped table instance. No serialization or
 * network overhead. This is the only implementation for the initial (in-process) deployment.
 *
 * <p>
 * Governed by: .decisions/table-partitioning/adr.md — in-process execution, remote-capable
 * interface.
 */
public final class InProcessPartitionClient implements PartitionClient {

    private final PartitionDescriptor descriptor;
    private final JlsmTable.StringKeyed table;

    /**
     * Creates an in-process partition client wrapping the given table.
     *
     * <p>
     * Contract:
     * <ul>
     * <li>Receives: descriptor for this partition, the backing JlsmTable.StringKeyed</li>
     * <li>Returns: partition client ready for operations</li>
     * <li>Side effects: none</li>
     * </ul>
     *
     * @param descriptor the partition descriptor; must not be null
     * @param table the backing table for this partition; must not be null
     */
    public InProcessPartitionClient(PartitionDescriptor descriptor, JlsmTable.StringKeyed table) {
        Objects.requireNonNull(descriptor, "descriptor must not be null");
        Objects.requireNonNull(table, "table must not be null");
        this.descriptor = descriptor;
        this.table = table;
    }

    @Override
    public PartitionDescriptor descriptor() {
        return descriptor;
    }

    @Override
    public void create(String key, JlsmDocument doc) throws IOException {
        assert key != null : "key must not be null";
        assert doc != null : "doc must not be null";
        Objects.requireNonNull(key, "key must not be null");
        Objects.requireNonNull(doc, "doc must not be null");
        table.create(key, doc);
    }

    @Override
    public Optional<JlsmDocument> get(String key) throws IOException {
        assert key != null : "key must not be null";
        Objects.requireNonNull(key, "key must not be null");
        return table.get(key);
    }

    @Override
    public void update(String key, JlsmDocument doc, UpdateMode mode) throws IOException {
        assert key != null : "key must not be null";
        assert doc != null : "doc must not be null";
        assert mode != null : "mode must not be null";
        Objects.requireNonNull(key, "key must not be null");
        Objects.requireNonNull(doc, "doc must not be null");
        Objects.requireNonNull(mode, "mode must not be null");
        table.update(key, doc, mode);
    }

    @Override
    public void delete(String key) throws IOException {
        assert key != null : "key must not be null";
        Objects.requireNonNull(key, "key must not be null");
        table.delete(key);
    }

    @Override
    public Iterator<TableEntry<String>> getRange(String fromKey, String toKey) throws IOException {
        assert fromKey != null : "fromKey must not be null";
        assert toKey != null : "toKey must not be null";
        Objects.requireNonNull(fromKey, "fromKey must not be null");
        Objects.requireNonNull(toKey, "toKey must not be null");
        return table.getAllInRange(fromKey, toKey);
    }

    /**
     * Not yet implemented — query execution through predicates requires QueryExecutor integration
     * which is handled by the coordinator in WU-3.
     *
     * @throws UnsupportedOperationException always
     */
    @Override
    public List<ScoredEntry<String>> query(Predicate predicate, int limit) throws IOException {
        throw new UnsupportedOperationException(
                "query execution is not implemented in InProcessPartitionClient; "
                        + "use the PartitionedTable coordinator (WU-3)");
    }

    @Override
    public void close() throws IOException {
        table.close();
    }
}

package jlsm.table.internal;

import jlsm.table.ScoredEntry;
import jlsm.table.TableEntry;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.Iterator;
import java.util.List;
import java.util.NoSuchElementException;
import java.util.Objects;
import java.util.PriorityQueue;

/**
 * Merges results from multiple partitions into a single result set.
 *
 * <p>
 * Contract: Stateless utility providing merge strategies for different query types. Each method
 * takes per-partition results and produces a globally correct merged result.
 *
 * <p>
 * Governed by:
 * .kb/distributed-systems/data-partitioning/vector-search-partitioning.md#result-fusion
 */
public final class ResultMerger {

    private ResultMerger() {
    }

    /**
     * Merges top-k scored results from multiple partitions by score (descending).
     *
     * <p>
     * Contract:
     * <ul>
     * <li>Receives: per-partition scored entry lists, global k limit</li>
     * <li>Returns: global top-k entries sorted by score descending</li>
     * <li>Side effects: none</li>
     * </ul>
     * Used for: vector similarity queries, full-text queries.
     *
     * @param partitionResults per-partition top-k results; must not be null
     * @param k global result limit; must be positive
     * @param <K> key type
     * @return merged top-k results sorted by score descending
     * @throws NullPointerException if partitionResults is null
     * @throws IllegalArgumentException if k is not positive
     */
    public static <K> List<ScoredEntry<K>> mergeTopK(List<List<ScoredEntry<K>>> partitionResults,
            int k) {
        Objects.requireNonNull(partitionResults, "partitionResults must not be null");
        if (k <= 0) {
            throw new IllegalArgumentException("k must be positive, got: " + k);
        }

        // Max-heap: highest score polled first
        final PriorityQueue<ScoredEntry<K>> heap =
                new PriorityQueue<>(Comparator.comparingDouble(ScoredEntry::score).reversed());

        for (final List<ScoredEntry<K>> partition : partitionResults) {
            assert partition != null : "individual partition result list must not be null";
            heap.addAll(partition);
        }

        final List<ScoredEntry<K>> result = new ArrayList<>(Math.min(k, heap.size()));
        int remaining = k;
        while (remaining > 0 && !heap.isEmpty()) {
            result.add(heap.poll());
            remaining--;
        }
        assert result.size() <= k : "result must contain at most k entries";
        return result;
    }

    /**
     * Merges range iteration results from multiple partitions in key order.
     *
     * <p>
     * Contract:
     * <ul>
     * <li>Receives: per-partition iterators (each already in key order)</li>
     * <li>Returns: single iterator producing entries in global key order</li>
     * <li>Side effects: none</li>
     * </ul>
     * Used for: property range queries, getAllInRange.
     *
     * @param partitionIterators per-partition iterators in key order; must not be null
     * @return merged iterator in global key order
     * @throws NullPointerException if partitionIterators is null
     */
    public static Iterator<TableEntry<String>> mergeOrdered(
            List<Iterator<TableEntry<String>>> partitionIterators) {
        Objects.requireNonNull(partitionIterators, "partitionIterators must not be null");
        return new MergingIterator(partitionIterators);
    }

    // -------------------------------------------------------------------------
    // MergingIterator — N-way merge via min-heap
    // -------------------------------------------------------------------------

    /**
     * An iterator that performs an N-way merge of pre-sorted partition iterators using a min-heap.
     * Each heap entry wraps the current head element from one partition iterator.
     */
    private static final class MergingIterator implements Iterator<TableEntry<String>> {

        /** Heap entry: the current head element from a single partition iterator. */
        private record HeapEntry(TableEntry<String> entry,
                Iterator<TableEntry<String>> source) {
        }

        private static final Comparator<HeapEntry> KEY_ORDER =
                Comparator.comparing(e -> e.entry().key());

        private final PriorityQueue<HeapEntry> heap;

        MergingIterator(List<Iterator<TableEntry<String>>> partitionIterators) {
            assert partitionIterators != null : "partitionIterators must not be null";
            this.heap = new PriorityQueue<>(Math.max(1, partitionIterators.size()), KEY_ORDER);
            for (final Iterator<TableEntry<String>> it : partitionIterators) {
                assert it != null : "individual partition iterator must not be null";
                if (it.hasNext()) {
                    heap.offer(new HeapEntry(it.next(), it));
                }
            }
        }

        @Override
        public boolean hasNext() {
            return !heap.isEmpty();
        }

        @Override
        public TableEntry<String> next() {
            if (heap.isEmpty()) {
                throw new NoSuchElementException("no more entries in merged iterator");
            }
            final HeapEntry head = heap.poll();
            assert head != null : "polled entry must not be null";
            // Advance the source iterator and re-offer its next element
            if (head.source().hasNext()) {
                heap.offer(new HeapEntry(head.source().next(), head.source()));
            }
            return head.entry();
        }
    }
}

